<script setup>
import Chart from 'chart.js/auto'
</script>

<template>
  <div class="relative w-full h-full">
    <canvas ref="chartCanvas"></canvas>
  </div>
</template>

<script>
/**
 * Chart.js wrapper for the API monitoring charts.
 *
 * Same library and SAME palette/typography as the infrastructure charts
 * (`src/views/infra/MonitoringChart.vue`) and the analytics ones, so the three
 * dashboards look like one product:
 *   text #e5e7eb · secondary text #9ca3af · border #374151
 *   grid rgba(55,65,81,.25) · tooltip rgba(17,24,39,.95)
 *
 * Two differences with the infra chart, both required by API metrics:
 *   • labels come from `row.label`, already formatted by useApiMonitoring
 *     (backend buckets are "YYYY-MM-DD HH:MM", not ISO timestamps);
 *   • each axis carries its OWN unit, because throughput (calls) and latency
 *     (ms) are drawn side by side on the left/right axes.
 *
 * Presentation only: it renders whatever `rows` + `metrics` receive and never
 * fetches anything.
 */
export default {
  name: 'ApiMonitoringChart',
  props: {
    /** Ordered buckets, e.g. `[{ label: '14:00', calls: 42, avg_ms: 310 }, …]`. */
    rows: {
      type: Array,
      default: () => []
    },
    /**
     * Series descriptors:
     * `{ key, label, color, type: 'line'|'bar', axis: 'y'|'y1', fill: boolean }`
     */
    metrics: {
      type: Array,
      default: () => []
    },
    /** Fixed upper bound of the left axis (rarely needed: counts are relative). */
    maxY: {
      type: Number,
      default: null
    },
    yTitle: {
      type: String,
      default: ''
    },
    y1Title: {
      type: String,
      default: ''
    },
    /** Suffix appended to the left axis values and their tooltip entries. */
    yUnit: {
      type: String,
      default: ''
    },
    /** Suffix appended to the right axis values and their tooltip entries. */
    y1Unit: {
      type: String,
      default: ''
    }
  },
  data() {
    return {
      chart: null
    }
  },
  computed: {
    chartData() {
      const rows = this.rows || []
      const labels = rows.map(row => row.label)
      const datasets = (this.metrics || []).map((metric) => {
        const color = metric.color || '#6366f1'
        const isBar = metric.type === 'bar'

        return {
          label: metric.label,
          data: rows.map(row => Number(row[metric.key] || 0)),
          type: isBar ? 'bar' : 'line',
          borderColor: color,
          backgroundColor: isBar
            ? `rgba(${this.hexToRgb(color)}, 0.55)`
            : `rgba(${this.hexToRgb(color)}, 0.12)`,
          borderWidth: isBar ? 0 : 2,
          tension: 0.35,
          fill: !!metric.fill && !isBar,
          pointRadius: 0,
          pointHoverRadius: 4,
          pointBackgroundColor: color,
          pointBorderWidth: 0,
          yAxisID: metric.axis || 'y'
        }
      })

      return { labels, datasets }
    },
    hasSecondaryAxis() {
      return (this.metrics || []).some(metric => (metric.axis || 'y') === 'y1')
    }
  },
  watch: {
    chartData: {
      handler() {
        this.updateChart()
      },
      deep: true
    }
  },
  methods: {
    hexToRgb(hex) {
      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
      return result
        ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
        : '99, 102, 241'
    },

    /** Compact value formatter ("1.2K", "480 ms"…) for one axis. */
    formatValue(value, unit = '') {
      const num = Number(value) || 0
      if (Math.abs(num) >= 1000) {
        const short = Math.abs(num) >= 1_000_000
          ? `${(num / 1_000_000).toFixed(1)}M`
          : `${(num / 1_000).toFixed(1)}K`
        return unit ? `${short}${unit}` : short
      }
      const text = Number.isInteger(num) ? String(num) : num.toFixed(1)
      return unit ? `${text}${unit}` : text
    },

    updateChart() {
      if (!this.$refs.chartCanvas) return

      if (this.chart) {
        // Replace data + options in place: recreating the chart on every refresh
        // would reset the hover state and flicker the canvas.
        this.chart.data = this.chartData
        this.chart.options = this.getChartOptions()
        this.chart.update('none')
      } else {
        this.initChart()
      }
    },

    initChart() {
      const ctx = this.$refs.chartCanvas?.getContext('2d')
      if (!ctx) return

      this.chart = new Chart(ctx, {
        type: 'line',
        data: this.chartData,
        options: this.getChartOptions()
      })
    },

    getChartOptions() {
      const palette = {
        text: '#e5e7eb',
        textSecondary: '#9ca3af',
        border: '#374151',
        grid: 'rgba(55, 65, 81, 0.25)',
        tooltip: 'rgba(17, 24, 39, 0.95)'
      }
      const font = { size: 12, family: "'Inter', sans-serif" }
      const titleFont = { size: 12, weight: '600', family: "'Inter', sans-serif" }

      return {
        responsive: true,
        maintainAspectRatio: false,
        // Live data: animation would fight with the refresh cadence.
        animation: false,
        interaction: {
          mode: 'index',
          intersect: false
        },
        plugins: {
          legend: {
            display: true,
            position: 'top',
            labels: {
              usePointStyle: true,
              boxWidth: 8,
              boxHeight: 8,
              padding: 12,
              font: titleFont,
              color: palette.text
            }
          },
          tooltip: {
            backgroundColor: palette.tooltip,
            padding: 10,
            borderColor: palette.border,
            borderWidth: 1,
            titleColor: palette.text,
            bodyColor: palette.textSecondary,
            titleFont,
            bodyFont: font,
            callbacks: {
              // Each dataset is formatted with the unit of ITS axis.
              label: (context) => {
                const unit = context.dataset.yAxisID === 'y1' ? this.y1Unit : this.yUnit
                return `${context.dataset.label}: ${this.formatValue(context.parsed.y, unit)}`
              }
            }
          }
        },
        scales: {
          y: {
            type: 'linear',
            display: true,
            position: 'left',
            beginAtZero: true,
            ...(this.maxY ? { max: this.maxY } : {}),
            grid: { color: palette.grid },
            ticks: {
              font,
              color: palette.textSecondary,
              callback: (value) => this.formatValue(value, this.yUnit)
            },
            title: this.yTitle
              ? { display: true, text: this.yTitle, font: titleFont, color: palette.text }
              : { display: false }
          },
          y1: {
            type: 'linear',
            display: this.hasSecondaryAxis,
            position: 'right',
            beginAtZero: true,
            grid: { drawOnChartArea: false },
            ticks: {
              font,
              color: palette.textSecondary,
              callback: (value) => this.formatValue(value, this.y1Unit)
            },
            title: this.y1Title
              ? { display: true, text: this.y1Title, font: titleFont, color: palette.text }
              : { display: false }
          },
          x: {
            grid: { display: false },
            ticks: {
              font,
              color: palette.textSecondary,
              maxRotation: 0,
              autoSkip: true,
              maxTicksLimit: 8
            }
          }
        }
      }
    }
  },
  mounted() {
    this.initChart()
  },
  beforeUnmount() {
    if (this.chart) {
      this.chart.destroy()
      this.chart = null
    }
  }
}
</script>
