<script>
/**
 * Chart.js wrapper for the API monitoring charts.
 *
 * Same library and SAME palette/typography as the infrastructure charts
 * (`src/views/infra/MonitoringChart.vue`) and the analytics ones, so the three
 * dashboards look like one product:
 *   text #e5e7eb · secondary text #9ca3af · border #374151
 *   grid rgba(55,65,81,.25) · tooltip rgba(17,24,39,.95)
 *
 * Two differences with the infra chart, both required by API metrics:
 *   • labels come from `row.label`, already formatted by useApiMonitoring
 *     (backend buckets are "YYYY-MM-DD HH:MM[:SS]", not ISO timestamps);
 *   • each axis carries its OWN unit, because throughput (calls) and latency
 *     (ms) are drawn side by side on the left/right axes.
 *
 * RENDER CONTRACT
 * ---------------
 * `update()` only repaints into the canvas size the chart ALREADY has, and the
 * chart lives inside a resizable dockview panel that is measured after mount.
 * That is why:
 *   • the instance is created one tick later (real panel size, not 0×0);
 *   • every render compares the canvas against its container and calls
 *     `resize()` when they differ — doing by hand what resizing the panel used
 *     to do;
 *   • data is patched in place (`labels`/`datasets`) instead of replacing the
 *     `data` object, and the instance is REBUILT only when the option signature
 *     changes (axes, units, series), because Chart.js keeps resolved scale
 *     options from construction time;
 *   • a ResizeObserver on the wrapper re-measures when dockview moves the panel
 *     (tab switch, split resize) without waiting for the next poll.
 *
 * Presentation only: it renders whatever `rows` + `metrics` receive and never
 * fetches anything.
 */
export default {
  name: 'ApiMonitoringChart',
  props: {
    /** Ordered buckets, e.g. `[{ label: '14:00:10', calls: 42, avg_ms: 310 }, …]`. */
    rows: {
      type: Array,
      default: () => []
    },
    /**
     * Series descriptors:
     * `{ key, label, color, type: 'line'|'bar', axis: 'y'|'y1', fill: boolean }`
     */
    metrics: {
      type: Array,
      default: () => []
    },
    /**
     * Monotonic counter bumped by the store on every committed refresh and on
     * every configuration change.
     *
     * The `chartData` watcher already catches the usual case (a brand new
     * `rows` array), but the counter makes the redraw deterministic: it fires
     * even when two consecutive payloads produce identical values, so "the
     * numbers changed" can never be missed by the canvas.
     */
    revision: {
      type: Number,
      default: 0
    },
    /** Fixed upper bound of the left axis (rarely needed: counts are relative). */
    maxY: {
      type: Number,
      default: null
    },
    yTitle: {
      type: String,
      default: ''
    },
    y1Title: {
      type: String,
      default: ''
    },
    /** Suffix appended to the left axis values and their tooltip entries. */
    yUnit: {
      type: String,
      default: ''
    },
    /** Suffix appended to the right axis values and their tooltip entries. */
    y1Unit: {
      type: String,
      default: ''
    }
  },
  data() {
    return {
      chart: null,
      // Option signature the live instance was built with.
      chartSignature: '',
      // Coalesces the watchers of a single tick into one render.
      renderPending: false,
      tooltip: {
        visible: false,
        title: '',
        items: [],
        top: '0px',
        left: '0px',
        transform: 'none'
      }
    }
  },
  computed: {
    chartData() {
      return this.buildChartData()
    },
    hasSecondaryAxis() {
      return (this.metrics || []).some(metric => (metric.axis || 'y') === 'y1')
    },
    /**
     * Everything that forces a NEW chart instance (Chart.js resolves scales and
     * tick callbacks at construction time, so these cannot be patched in place).
     */
    optionsSignature() {
      const metrics = (this.metrics || []).map(metric => ([
        metric.key,
        metric.label,
        metric.color,
        metric.type || 'line',
        metric.axis || 'y',
        !!metric.fill
      ]))
      return JSON.stringify({
        metrics,
        maxY: this.maxY,
        yTitle: this.yTitle,
        y1Title: this.y1Title,
        yUnit: this.yUnit,
        y1Unit: this.y1Unit
      })
    }
  },
  watch: {
    /** Data changed: repaint (no rebuild needed). */
    chartData: {
      handler() {
        this.scheduleRender()
      },
      deep: true
    },
    /** Explicit refresh signal from the store (see the prop documentation). */
    revision() {
      this.scheduleRender()
    },
    /** Configuration changed: axes/units/series → rebuild the instance. */
    optionsSignature() {
      this.scheduleRender()
    }
  },
  methods: {
    hexToRgb(hex) {
      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
      return result
        ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
        : '99, 102, 241'
    },

    /** Compact value formatter ("1.2K", "480 ms"…) for one axis. */
    formatValue(value, unit = '') {
      const num = Number(value) || 0
      if (Math.abs(num) >= 1000) {
        const short = Math.abs(num) >= 1_000_000
          ? `${(num / 1_000_000).toFixed(1)}M`
          : `${(num / 1_000).toFixed(1)}K`
        return unit ? `${short}${unit}` : short
      }
      const text = Number.isInteger(num) ? String(num) : num.toFixed(1)
      return unit ? `${text}${unit}` : text
    },

    /** Fresh plain objects: Chart.js is free to decorate them in place. */
    buildChartData() {
      const rows = this.rows || []
      const labels = rows.map(row => row.label)
      const datasets = (this.metrics || []).map((metric) => {
        const color = metric.color || '#6366f1'
        const isBar = metric.type === 'bar'

        return {
          label: metric.label,
          data: rows.map(row => Number(row[metric.key] || 0)),
          type: isBar ? 'bar' : 'line',
          borderColor: color,
          backgroundColor: isBar
            ? `rgba(${this.hexToRgb(color)}, 0.55)`
            : `rgba(${this.hexToRgb(color)}, 0.12)`,
          borderWidth: isBar ? 0 : 2,
          tension: 0.35,
          fill: !!metric.fill && !isBar,
          pointRadius: 0,
          pointHoverRadius: 4,
          pointBackgroundColor: color,
          pointBorderWidth: 0,
          yAxisID: metric.axis || 'y'
        }
      })

      return { labels, datasets }
    },

    /** True when the canvas no longer matches the box it paints into. */
    hasSizeChanged() {
      const parent = this.$refs.chartCanvas?.parentElement
      if (!parent || !this.chart) return false

      const width = Math.round(parent.clientWidth)
      const height = Math.round(parent.clientHeight)
      // Hidden panel: nothing to measure yet, the observer/next refresh handles it.
      if (!width || !height) return false

      return Math.round(this.chart.width || 0) !== width
        || Math.round(this.chart.height || 0) !== height
    },

    /** One render per tick, whatever combination of watchers fired. */
    scheduleRender() {
      if (this.renderPending) return
      this.renderPending = true
      this.$nextTick(() => {
        this.renderPending = false
        this.render()
      })
    },

    render() {
      if (!this.$refs.chartCanvas) return

      if (!this.chart) {
        this.createChart()
        return
      }

      // Different axes/units/series: the resolved scale config of the running
      // instance is stale, so patch nothing — build a new one.
      if (this.optionsSignature !== this.chartSignature) {
        this.recreateChart()
        return
      }

      // Patch in place: `chart.data = …` is not a supported mutation and leaves
      // the internal metasets pointing at the previous arrays.
      const data = this.buildChartData()
      this.chart.data.labels = data.labels
      this.chart.data.datasets = data.datasets

      if (this.hasSizeChanged()) {
        // The container changed since the last frame (panel resized, or the
        // chart was born before dockview measured it). `update()` would keep
        // painting the old frame — `resize()` re-reads the container and
        // repaints, exactly what manually resizing the panel used to do.
        this.chart.resize()
      } else {
        this.chart.update('none')
      }
    },

    createChart() {
      const ctx = this.$refs.chartCanvas?.getContext('2d')
      if (!ctx) return

      this.hideTooltip()
      this.chartSignature = this.optionsSignature
      this.chart = new Chart(ctx, {
        type: 'line',
        data: this.buildChartData(),
        options: this.getChartOptions()
      })

      // The first frame may have been measured against a panel that was still
      // hidden (0×0 canvas): re-measure as soon as the layout is final.
      this.$nextTick(() => {
        if (this.chart && this.hasSizeChanged()) this.chart.resize()
      })
    },

    recreateChart() {
      this.destroyChart()
      this.createChart()
    },

    destroyChart() {
      if (this.chart) {
        this.chart.destroy()
        this.chart = null
      }
      this.hideTooltip()
    },

    /* ── Overlay tooltip ────────────────────────────────────────────────── */

    handleExternalTooltip(context) {
      const model = context?.tooltip
      if (!model || !model.opacity || !model.dataPoints?.length) {
        this.hideTooltip()
        return
      }

      const items = model.dataPoints.map(point => ({
        id: `${point.datasetIndex}-${point.dataIndex}`,
        label: point.dataset?.label || '',
        color: point.dataset?.borderColor || '#6366f1',
        value: this.formatValue(
          point.parsed?.y,
          point.dataset?.yAxisID === 'y1' ? this.y1Unit : this.yUnit
        )
      }))

      this.tooltip = {
        visible: true,
        title: String(model.title?.[0] || model.dataPoints[0].label || ''),
        items,
        ...this.overlayPosition(model.caretX, model.caretY)
      }
    },

    /** Keeps the overlay inside the panel and flips it past the middle. */
    overlayPosition(x, y) {
      const wrap = this.$refs.wrapEl
      const width = wrap?.clientWidth || 0
      const height = wrap?.clientHeight || 0
      const gap = 14
      const placeLeft = width > 0 && x > width * 0.6
      const left = Math.max(0, Math.min(placeLeft ? x - gap : x + gap, width))
      const top = Math.max(0, Math.min(y - 12, Math.max(height - 24, 0)))

      return {
        left: `${Math.round(left)}px`,
        top: `${Math.round(top)}px`,
        transform: placeLeft ? 'translate(-100%, 0)' : 'none'
      }
    },

    hideTooltip() {
      if (this.tooltip.visible) {
        this.tooltip = { ...this.tooltip, visible: false, items: [] }
      }
    },

    /* ── Options ────────────────────────────────────────────────────────── */

    getChartOptions() {
      const palette = {
        text: '#e5e7eb',
        textSecondary: '#9ca3af',
        border: '#374151',
        grid: 'rgba(55, 65, 81, 0.25)',
        tooltip: 'rgba(17, 24, 39, 0.95)'
      }
      const font = { size: 12, family: "'Inter', sans-serif" }
      const titleFont = { size: 12, weight: '600', family: "'Inter', sans-serif" }

      return {
        responsive: true,
        maintainAspectRatio: false,
        // Live data: animation would fight with the refresh cadence.
        animation: false,
        interaction: {
          mode: 'index',
          intersect: false
        },
        plugins: {
          legend: {
            display: true,
            position: 'top',
            labels: {
              usePointStyle: true,
              boxWidth: 8,
              boxHeight: 8,
              padding: 12,
              font: titleFont,
              color: palette.text
            }
          },
          tooltip: {
            // The canvas tooltip is replaced by the overlay rendered above.
            enabled: false,
            external: (context) => this.handleExternalTooltip(context),
            mode: 'index',
            intersect: false,
            backgroundColor: palette.tooltip,
            padding: 10,
            borderColor: palette.border,
            borderWidth: 1,
            titleColor: palette.text,
            bodyColor: palette.textSecondary,
            titleFont,
            bodyFont: font,
            callbacks: {
              // Each dataset is formatted with the unit of ITS axis.
              label: (context) => {
                const unit = context.dataset.yAxisID === 'y1' ? this.y1Unit : this.yUnit
                return `${context.dataset.label}: ${this.formatValue(context.parsed.y, unit)}`
              }
            }
          }
        },
        scales: {
          y: {
            type: 'linear',
            display: true,
            position: 'left',
            beginAtZero: true,
            ...(this.maxY ? { max: this.maxY } : {}),
            grid: { color: palette.grid },
            ticks: {
              font,
              color: palette.textSecondary,
              callback: (value) => this.formatValue(value, this.yUnit)
            },
            title: this.yTitle
              ? { display: true, text: this.yTitle, font: titleFont, color: palette.text }
              : { display: false }
          },
          y1: {
            type: 'linear',
            display: this.hasSecondaryAxis,
            position: 'right',
            beginAtZero: true,
            grid: { drawOnChartArea: false },
            ticks: {
              font,
              color: palette.textSecondary,
              callback: (value) => this.formatValue(value, this.y1Unit)
            },
            title: this.y1Title
              ? { display: true, text: this.y1Title, font: titleFont, color: palette.text }
              : { display: false }
          },
          x: {
            grid: { display: false },
            ticks: {
              font,
              color: palette.textSecondary,
              maxRotation: 0,
              autoSkip: true,
              maxTicksLimit: 8
            }
          }
        }
      }
    }
  },
  mounted() {
    // One tick: dockview mounts the panel and only then measures the group, so
    // creating the chart synchronously can leave it with a 0×0 canvas.
    this.$nextTick(() => this.createChart())

    // The panel can be resized/shown long after the last refresh; without this
    // the graph would keep the frame measured while it was hidden.
    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => this.scheduleRender())
      if (this.$refs.wrapEl) this.resizeObserver.observe(this.$refs.wrapEl)
    }
  },
  beforeUnmount() {
    if (this.resizeObserver) {
      this.resizeObserver.disconnect()
      this.resizeObserver = null
    }
    this.destroyChart()
  }
}
</script>
